import {
  addMongoDatabase,
  addMySQLDatabase,
  addPostgresDatabase,
  restore,
  setupWritableDB,
  snapshot,
} from "e2e/support/helpers";

describe("qa databases snapshots", { tags: "@external" }, () => {
  it("creates snapshots for supported qa databases", () => {
    // Mongo
    restoreAndAuthenticate();

    addMongoDatabase();
    snapshot("mongo-5");

    // Postgres
    restoreAndAuthenticate();

    addPostgresDatabase();
    snapshot("postgres-12");

